actions.script:
// Google's siteverify takes the secret and the response as parameters (RestClient puts body parameters in the query)
const restResponse = ec.service.rest().method("POST")
        .uri("https://www.google.com/recaptcha/api/siteverify").addHeader("Content-Type", "application/json")
        .addBodyParameter("secret", reCaptchaSecret).addBodyParameter("response", reCaptchaToken).call()
let respMap = null
try { respMap = restResponse.jsonObject() } catch (e) { respMap = null }
if (restResponse.statusCode < 200 || restResponse.statusCode >= 300 || !respMap?.success) {
    ec.logger.warn(`Unsuccessful reCAPTCHA verify: ${JSON.stringify(respMap)}`)
    ec.message.addPublic(ec.l10n.localize("Could not validate reCAPTCHA response, confirm you are not a robot"), "warning")
    ec.message.addError(ec.l10n.localize("Could not verify reCAPTCHA token"))
    return
}
ec.logger.info(`Successful reCAPTCHA verify: ${JSON.stringify(respMap)}`)
